    TORCH_CHECK(Q.scalar_type() == at::kHalf && K.scalar_type() == at::kHalf && V.scalar_type() == at::kHalf,
                "Only float16 supported");
    TORCH_CHECK(Q.dim() == 4, "Expect [B,H,S,D]");
    TORCH_CHECK(Q.sizes() == K.sizes() && Q.sizes() == V.sizes(), "Q,K,V must have same shape");

    auto Qc = Q.contiguous();
    auto Kc = K.contiguous();
    auto Vc = V.contiguous();

    int B = (int)Qc.size(0);
    int H = (int)Qc.size(1);
    int SEQ = (int)Qc.size(2);
    int D = (int)Qc.size(3);
    int BH = B * H;

    auto O = torch::empty_like(Qc);

    constexpr int BLOCK_M = 16;
    constexpr int DK = 64;
    constexpr int DV = 64;
    constexpr int THREADS = 256;

    float scale = 1.0f / sqrtf((float)D);

    size_t qk_bytes = (size_t)BLOCK_M * DK * sizeof(cute::half_t) + (size_t)SEQ * DK * sizeof(cute::half_t);
    size_t v_bytes  = (size_t)SEQ * DV * sizeof(cute::half_t);
    size_t swap_bytes = qk_bytes > v_bytes ? qk_bytes : v_bytes;
    swap_bytes = (swap_bytes + 7) & ~size_t(7);
    size_t s_bytes = (size_t)BLOCK_M * SEQ * sizeof(float);
    size_t total_smem = swap_bytes + s_bytes;

    dim3 grid((SEQ + BLOCK_M - 1) / BLOCK_M, BH);
    dim3 block(THREADS);

    auto kernel = fused_attention_kernel<cute::half_t, BLOCK_M, DK, DV, THREADS>;
    int device_id = 0;
    cudaGetDevice(&device_id);
    int max_smem_optin = 0;
    cudaDeviceGetAttribute(&max_smem_optin, cudaDevAttrMaxSharedMemoryPerBlockOptin, device_id);
    TORCH_CHECK((size_t)max_smem_optin >= total_smem,
                "fused_attention_kernel: requested shared memory (", total_smem,
                " bytes) exceeds device limit (", max_smem_optin, " bytes)");
    cudaError_t attr_err = cudaFuncSetAttribute(kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)total_smem);
    TORCH_CHECK(attr_err == cudaSuccess, "cudaFuncSetAttribute failed: ", cudaGetErrorString(attr_err));

    cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

    kernel<<<grid, block, total_smem, stream>>>(
        reinterpret_cast<const cute::half_t*>(Qc.data_ptr<at::Half>()),
        reinterpret_cast<const cute::half_t*>(Kc.data_ptr<at::Half>()),
        reinterpret_cast<const cute::half_t*>(Vc.data_ptr<at::Half>()),
        reinterpret_cast<cute::half_t*>(O.data_ptr<at::Half>()),
        BH, SEQ, D, scale);

    auto err = cudaGetLastError();
    TORCH_CHECK(err == cudaSuccess, "fused_attention_kernel launch failed: ", cudaGetErrorString(err));

    return O;
}
